(33, 'test akurasi lexrank lagi', '2026-06-09 22:30:23', 'Upload', 'transkrip_Zoom Meeting   Psikologi Sosial I C 2022 02 23 13 15 57_20260609_223612.txt', 2035, 'adalah notulensi rapat berdasarkan transkrip rapat yang Anda berikan:\n\n**Pembukaan:**\n\n- Perkuliahan dibuka oleh dosen pengampu pada sesi pertama mata kuliah Dasar Manajemen dan Bisnis.\n- Agenda sesi ini adalah membahas definisi organisasi, struktur, efisiensi, dan efektivitas.\n\n**Definisi Organisasi:**\n\n- Organisasi adalah kumpulan orang yang bekerja secara terkoordinasi untuk mencapai tujuan bersama yang telah ditetapkan.\n- Tujuan organisasi dapat berupa profit (keuntungan finansial), pertumbuhan bisnis, atau peningkatan pelayanan kepada masyarakat.\n\n**Pertanyaan dan Diskusi:**\n\n- Pertanyaan: Apa perbedaan antara efisiensi dan efektivitas?\n - Jawaban: Efisiensi berfokus pada cara penggunaan sumber daya (hemat, tanpa pemborosan), sedangkan efektivitas berfokus pada ketercapaian tujuan akhir yang telah ditetapkan organisasi.\n\n**Kesimpulan:**\n\n- Organisasi yang baik harus mampu mencapai tujuannya (efektif) sekaligus menggunakan sumber daya secara optimal (efisien).\n- Struktur organisasi yang jelas menjadi fondasi penting untuk mencapai kedua hal tersebut.\n\n**Penutup:**\n\n- Rapat ditutup dengan penyelesaian tugas-tugas yang telah dibahas dan pengumuman tentang kegiatan selanjutnya.', '', '2026-06-09 15:30:23');
INSERT INTO `notulensi_hasil` (`id`, `judul_rapat`, `waktu_rapat`, `tipe_transkripsi`, `transkrip_txt`, `durasi_detik`, `ringkasan`, `file_pdf`, `created_at`) VALUES
(34, 'Zoom Meeting Psikologi Sosial I C 2022 02 23 13 15 57', '2026-06-09 20:08:19', 'Upload', 'whisper transkrip psikologi.txt', 0, 'Disini psikologi sosial mungkin udah saya bahas sebenarnya minggu lalu ya, bahwa awal mulanya munculnya psikologi sosial itu adalah dari ilmuwan Jerman, dilenggan Jerman yang. Ini membahas psikologi sosial, tapi dari perspektif yang berbeda. Sedangkan Edward Ross atau ini sosialok Amerika, dia melihat bahwa psikologi sosial ini nanti ranahnya adalah masyarakat, atau lingkungan sosial mempengaruhi individu, Jadi ada dua sudut pandang yang berbeda.\r\n\r\nDia mengatakan bahwa bagaimana individu di penghari oleh lingkungan ya oleh masyarakat dan juga bagaimana mumpur sikap dalam situasi-situasi sosial, Cipap dalam situasi-situasi sosial. Atau perilaku kalian dipengaruh oleh adanya saya disini, Itu aktual, aktual ya, Imagine itu, yang seperti apa, Semuanya temen-temen. Hmm, oke dia belum pernah ketemu tapi seperti benar-benar ketemu gitu ya?\r\n\r\nBetul, kayak norma-norma yang kita udah sama-sama tahu gitu yang jadi dia tersirat kita sudah kayak paham aja lah gitu, antorannya seperti itu. Situasi sosial ini memang ilmu, bukan common sense ya, Nanti kita bahas lebih lanjut. Teman-teman tahu kira-kira apa situasi, tampoh situasi sosial, Yang sehari-hari aja, Iya, Lani, Jadi ada interaksi di kelas itu?\r\n\r\nBetul, ya ketika ada interaksi antar dua atau lebih orang, itu benar-benar termasuk dalam situasi sosial. Disini menurut Lewin, psikologi sosial itu untuk mempelajari tentang perilaku-perilaku individu jauh aku individu tapi dalam situasi sosial yang ketika memang ada infaksi antar-individu gitu ya, Beeren juga memberpendapat yang sama sebenarn. Ibu, lainnya sih berkanya, Ibu, tentang yang implied, implied presence.\r\n\r\nDia tidak ada tapi kita membayangkan dia ada di sini. Itu kalau itu aja inget aja yang lebih ke normal-normal atau aturan-aturan seperti itu, Itu jelas kira-kira, Terima kasih, Udah buk baik, terima kasih ya Bu, Oke, ya Sekar. Dia ngomong-ngomong depan kaca akibat adanya kehadiran orang lainnya, dia bisa aja yang aktual atau yang dia bayang.\r\n\r\nKarena ada kehadiran orang lain, menurut sih Alport ya, menurut Alport itu masuk ke dalam ranahnya psikologi sosial. Kalau psikologi sosial, dia individu, gitu, lebih kepada perilaku individu, tapi. Tapi kepada perilaku individu, tapi dipelengaruhi oleh masyarakat sosial, lingkungan sosial.\r\n\r\nKita lanjut ke, ini, psikologi sosial sebagai ilmu. Ijin Bu, kalau menurut Rani yang lebih, ya benar-benar itu yang itu bukan ke-mini kok sekolah berdua, karena terlalu banyak orang terlibat dalam suatu keperdaman, kurang baik. Ini beda-beda nih ya pendapat sekar, menapa Lani, Andra, Ivana semua beda, jadi nah karena ada perbedaan-perbedaan pendapat itu Mungkin muncul lah psikologi sosial di sini, ini kan salah satu konteks teamwork.\r\n\r\nIni kan salah satu konteks teamwork ya, ini kerja kelompok. Kerja kelompok ini kan salah satu kelasi sosial ya, ketika kita harus bekerja dalam satu kelompok. Bahwa yang sejenis itu akan, nah Andra kenapa, Kira-kira Andra lebih relate ke yang atas, Halo, ya Andra gimana?\r\n\r\nKarena menurut saya kalau misalnya terlalu banyak kesamaan, jadi nggak ada sesuatu yang bisa diceritahu.\r\n', '', '2026-06-09 15:44:21'),
(35, 'Zoom Meeting Psikologi Sosial I C 2022 02 23 13 15 57 (LLM Only)', '2026-06-09 20:08:19', 'Upload', 'whisper transkrip psikologi.txt', 0, 'Berikut adalah notulensi rapat berdasarkan transkrip yang diberikan:\r\n\r\n**Pembukaan**\r\n\r\n- Siapa yang membuka: Tidak disebutkan\r\n- Kapan: Tidak disebutkan\r\n- Apa agenda rapat/kuliah, siapa yang hadir jika disebutkan: Tidak disebutkan\r\n\r\n**Sejarah Psikologi Sosial**\r\n\r\n- Definisi psikologi sosial menurut Alport: Psikologi sosial adalah ilmu pengetahuan yang menggunakan metode ilmiah untuk memahami bagaimana pikiran, perasaan, dan perilaku individu dipengaruhi oleh kehadiran orang lain.\r\n- Tiga jenis kehadiran:\r\n  - Kehadiran aktual: Keberadaan fisik orang lain\r\n  - Kehadiran imaging: Bayangan atau gambaran orang lain yang tidak nyata\r\n  - Kehadiran implied: Norma-norma sosial yang tidak tertulis dan mempengaruhi perilaku individu\r\n\r\n**Perbedaan Psikologi Sosial dengan Ilmu Lain**\r\n\r\n- Perbandingan psikologi sosial dengan sosiologi:\r\n  - Unit analisis: Masyarakat (sosiologi) vs. Individu (psikologi sosial)\r\n- Perbandingan psikologi sosial dengan antropologi:\r\n  - Fokus: Budaya dan kebudayaan (antropologi) vs. Aspek fisik manusia (biologi)\r\n\r\n**Pertanyaan dan Diskusi**\r\n\r\n- Pertanyaan: Bagaimana perbedaan psikologi sosial dengan ilmu lain?\r\n- Jawaban: Psikologi sosial memiliki fokus pada individu dan kehadiran orang lain, sedangkan sosiologi lebih fokus pada sistem masyarakat. Antropologi juga memiliki fokus pada budaya dan kebudayaan.\r\n\r\n**Kesimpulan**\r\n\r\n- Poin simpulan utama:\r\n  - Psikologi sosial perlu menggunakan pendekatan ilmiah untuk memahami perilaku individu.\r\n  - Pengalaman individu unik dan tidak bisa dijadikan dasar informasi yang konsisten.\r\n\r\n**Penutup**\r\n\r\n- Bagaimana rapat/kuliah ditutup: Tidak disebutkan\r\n', '', '2026-06-09 15:59:25'),
(36, 'data test akurasi whisper lexrank', '2026-06-10 21:18:22', 'Upload', 'transkrip_Mentoring Digital Marketing Melalui Zoom Meeting PENS SKY Venture - PENS SKY Venture 1080p h264_2_20260610_214445.txt', 8156, '**Pembukaan:**\n- Rapat dibuka oleh Pak Mobed\n- Agenda rapat: digital marketing for startup\n- Hadir dalam rapat: temen-temen, Pak Moabit, dan lain-lain\n\n**Digital Marketing untuk Startup:**\n- Digital marketing adalah konsep yang berfokus pada penggunaan teknologi digital untuk meningkatkan kesadaran dan penjualan produk atau jasa.\n- Digital marketing dapat digunakan oleh startup untuk meningkatkan visibilitas dan keuntungan mereka.\n- Pak Mobed menjelaskan bahwa digital marketing memiliki beberapa komponen, seperti SEO, social media marketing, email marketing, dan lain-lain.\n\n**Topik Utama 1: Konsep Digital Marketing:**\n- Pak Mobed menjelaskan bahwa konsep digital marketing adalah tentang membuat konten yang relevan dan menarik untuk target audiens.\n- Ia juga menjelaskan bahwa digital marketing dapat digunakan untuk meningkatkan kesadaran dan penjualan produk atau jasa.\n- Contoh dari digital marketing adalah penggunaan social media, email marketing, dan SEO.\n\n**Topik Utama 2: Strategi Digital Marketing:**\n- Pak Mobed menjelaskan bahwa strategi digital marketing harus disesuaikan dengan kebutuhan target audiens.\n- Ia juga menjelaskan bahwa strategi digital marketing dapat digunakan untuk meningkatkan kesadaran dan penjualan produk atau jasa.\n- Contoh dari strategi digital marketing adalah penggunaan social media, email marketing, dan SEO.\n\n**Pertanyaan dan Diskusi:**\n- Pak Mobed menjawab pertanyaan tentang bagaimana membuat konten yang relevan dan menarik untuk target audiens.\n- Ia juga menjelaskan bahwa digital marketing dapat digunakan untuk meningkatkan kesadaran dan penjualan produk atau jasa.\n\n**Kesimpulan:**\n- Pak Mobed menyimpulkan bahwa digital marketing adalah konsep yang berfokus pada penggunaan teknologi digital untuk meningkatkan kesadaran dan penjualan produk atau jasa.\n- Ia juga menjelaskan bahwa strategi digital marketing harus disesuaikan dengan kebutuhan target audiens.\n\n**Penutup:**\n- Pak Mobed mengucapkan terima kasih kepada hadirin dalam rapat tersebut.', '', '2026-06-10 14:18:22'),
(37, 'Zoom Meeting   Psikologi Sosial I C 2022 02 23 13 15 57', '2026-06-10 22:23:25', 'Upload', 'transkrip_Zoom Meeting   Psikologi Sosial I C 2022 02 23 13 15 57_20260610_222920.txt', 2035, 'adalah notulensi rapat berdasarkan transkrip yang diberikan:\n\n**Pembukaan:**\n\n- Rapat ini dibuka oleh Maren, yang membaca sekilas tugas-tugas yang telah dikumpulkan oleh mahasiswa.\n- Agenda rapat: review sejarah psikologi sosial dan pembahas topik-topik terkait.\n\n**Topik Utama 1: Definisi Psikologi Sosial:**\n\n- Psikologi sosial adalah ilmu yang mempelajari bagaimana pikiran, perasaan, dan perilaku individu dipengaruhi oleh lingkungan sosial.\n- Tiga konsep utama dalam psikologi sosial:\n 1. Actual (kehadiran nyata): kehadiran seseorang atau sesuatu yang mempengaruhi perilaku individu secara langsung.\n 2. Imaging (pembayangan): kehadiran seseorang atau sesuatu yang dipikirkan oleh individu, meskipun tidak ada secara fisik.\n 3. Implied (tersirat): kehadiran seseorang atau sesuatu yang tidak terlihat secara langsung, tetapi dapat mempengaruhi perilaku individu.\n\n**Topik Utama 2: Perbedaan Psikologi Sosial dengan Ilmu Lain:**\n\n- Psikologi sosial berbeda dari ilmu lain seperti sosiologi dan antropologi dalam hal unit analisis.\n- Sosiologi fokus pada sistem masyarakat, sedangkan psikologi sosial fokus pada perilaku individu yang dipengaruhi oleh lingkungan sosial.\n\n**Pertanyaan dan Diskusi:**\n\n- Pertanyaan: Bagaimana cara membedakan actual, imaging, dan implied dalam konteks psikologi sosial?\n- Jawaban: Actual adalah kehadiran nyata, imaging adalah kehadiran seseorang atau sesuatu yang dipikirkan oleh individu, sedangkan implied adalah kehadiran seseorang atau sesuatu yang tidak terlihat secara langsung tetapi dapat mempengaruhi perilaku individu.\n\n**Kesimpulan:**\n\n- Psikologi sosial memiliki peran penting dalam memahami bagaimana lingkungan sosial mempengaruhi perilaku individu.\n- Ilmu ini dapat membantu kita memahami bagaimana kehadiran seseorang atau sesuatu', '', '2026-06-10 15:23:25'),
